module multi_pipe_8bit(
    input clk, 
    input rst_n, 
    input mul_en_in, 
    input [7:0] mul_a, 
    input [7:0] mul_b, 
    output mul_en_out, 
    output [15:0] mul_out
);
// TODO: Please add your solution here
reg [3:0] mul_en_out_reg;
reg [7:0] mul_a_reg,mul_b_reg;
reg [15:0] temp[0:7];
reg [15:0] sum[0:7];
reg [15:0] mul_out_reg;
integer i;
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		mul_en_out_reg <= 4'd0;
	end
	else begin
		mul_en_out_reg <= {mul_en_out_reg[2:0],mul_en_in};
	end
end
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		mul_a_reg <= 8'd0;
		mul_b_reg <= 8'd0;
	end
	else if(mul_en_in)begin
		mul_a_reg <= mul_a;
		mul_b_reg <= mul_b;
	end
end
genvar j;
generate
	for(j=0;j<8;j=j+1)begin
		assign temp[j][15:0] = ({8{mul_b_reg[j]}}&mul_a_reg);
	end
endgenerate
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		sum[0] <= 16'd0;
		sum[1] <= 16'd0;
		sum[2] <= 16'd0;
		sum[3] <= 16'd0;
		sum[4] <= 16'd0;
		sum[5] <= 16'd0;
		sum[6] <= 16'd0;
		sum[7] <= 16'd0;
	end
	else begin
		sum[0] <= temp[0];
		sum[1] <= temp[1]+temp[2];
		sum[2] <= temp[3]+temp[4];
		sum[3] <= temp[5]+temp[6];
		sum[4] <= temp[7];
		sum[5] <= sum[1]+sum[2];
		sum[6] <= sum[3]+sum[4];
		sum[7] <= sum[5]+sum[6];
	end
end
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		mul_out_reg <= 16'd0;
	end
	else begin
		mul_out_reg <= sum[0]+sum[7];
	end
end
assign mul_en_out = mul_en_out_reg[2];
assign mul_out = mul_en_out_reg[2]?mul_out_reg:0;
endmodule
